        assertEquals("0", contador(c575), "fact-rescate-normal-con-comision-arma-el-movimiento-foe-con-iva-19 :: counter of the output");
        assertEquals(List.of("CalculaCustodiaRescate", "ProcesarCustodiaFondoMutuo", "CrearCargoAbono", "CrearMovimientoComprobante"), orden(c575), "fact-rescate-normal-con-comision-arma-el-movimiento-foe-con-iva-19 :: order of the calls to the collaborators");
